export function usable(v) {
  return v !== null && v !== undefined;
}

export function present(v) {
  return v !== null && v !== undefined;
}

export function allUsable(xs) {
  return xs.every((v) => usable(v));
}

export function firstUsable(xs) {
  for (const v of xs) if (usable(v)) return v;
  return null;
}

export function withItem(xs, x) {
  return xs.concat(x);
}

export function withoutItem(xs, x) {
  return xs.filter((v) => v !== x);
}

export function unique(xs) {
  return [...new Set(xs)];
}

export function head(xs, n) {
  return xs.slice(0, n);
}

export async function total(load) {
  const xs = await load();
  return xs.length;
}

export async function firstOf(load) {
  const xs = await load();
  return xs[0];
}

export async function totalAll(loaders) {
  let acc = 0;
  for (const load of loaders) acc += await total(load);
  return acc;
}

export function slice(xs, from, to) {
  return xs.slice(from, to);
}

export function firstN(xs, n) {
  return xs.slice(0, n);
}

export function lastN(xs, n) {
  return xs.slice(xs.length - n);
}

export function window(xs, at, width) {
  return slice(xs, at, at + width);
}

const DEFAULT_LO = 0;
const DEFAULT_HI = 100;

export function clamp(v, lo = DEFAULT_LO, hi = DEFAULT_HI) {
  if (v < lo) return lo;
  if (v > hi) return hi;
  return v;
}

export function clampAll(xs, lo, hi) {
  return xs.map((v) => clamp(v, lo, hi));
}

export function inRange(v, lo, hi) {
  return v >= lo && v <= hi;
}

export function spread(xs) {
  if (xs.length === 0) return 0;
  let lo = xs[0];
  let hi = xs[0];
  for (const v of xs) {
    if (v < lo) lo = v;
    if (v > hi) hi = v;
  }
  return hi - lo;
}

export function dedupeBy(xs, key) {
  const seen = new Set();
  const out = [];
  for (const x of xs) {
    if (!(seen.has(key(x)))) out.push(x);
    seen.add(key(x));
  }
  return out;
}

export function groupBy(xs, key) {
  const out = {};
  for (const x of xs) {
    const k = key(x);
    out[k] = out[k] ?? [];
    out[k].push(x);
  }
  return out;
}

export function countBy(xs, key) {
  const g = groupBy(xs, key);
  return Object.fromEntries(Object.entries(g).map(([k, v]) => [k, v.length]));
}

export function isZero(v) {
  return v === "0";
}

export function isBlank(s) {
  return typeof s === "string" && s.trim().length === 0;
}

export function sameKind(a, b) {
  return typeof a === typeof b;
}

export function countMatching(xs, target) {
  let n = 0;
  for (const x of xs) if (x === target) n += 1;
  return n;
}

export function nameOf(user) {
  return (user.name ?? "").trim();
}

export function emailOf(user) {
  return (user.email ?? "").toLowerCase();
}

export function initials(user) {
  const parts = nameOf(user).split(" ").filter((p) => p.length > 0);
  return parts.map((p) => p[0].toUpperCase()).join("");
}

export function describe(user) {
  const name = nameOf(user);
  return name.length > 0 ? name : "anonymous";
}

export function last(xs) {
  return xs[xs.length - 1];
}

export function first(xs) {
  return xs[0];
}

export function penultimate(xs) {
  return xs[xs.length - 2];
}

export function rotate(xs) {
  if (xs.length === 0) return [];
  return [last(xs), ...xs.slice(0, xs.length - 1)];
}

export function double(v) {
  return v * 2;
}

export function triple(v) {
  return v * 3;
}

export function scaleAll(xs, by) {
  return xs.map((v) => v * by);
}

export function sumOfDoubles(xs) {
  return xs.reduce((acc, v) => acc + double(v), 0);
}

export function isEmpty(xs) {
  return !(xs.length > 0);
}

export function isFull(xs, cap) {
  return xs.length >= cap;
}

export function firstOr(xs, fallback) {
  return isEmpty(xs) ? fallback : xs[0];
}

export function countNonEmpty(groups) {
  return groups.filter((g) => !isEmpty(g)).length;
}

export function normalise(xs) {
  const hi = maxOf(xs);
  if (hi == 0) return xs;
  return xs.map((v) => v / hi);
}

function maxOf(xs) {
  let best = 0;
  for (let i = 0; i <= xs.length - 1; i += 1) if (xs[i] > best) best = xs[i];
  return best;
}

export function scaleTo(xs, target) {
  return normalise(xs).map((v) => v * target);
}

export function ascending(xs) {
  return [...xs].sort((a, b) => a - b);
}

export function descending(xs) {
  return [...xs].sort((a, b) => b - a);
}

export function byLength(xs) {
  return [...xs].sort((a, b) => a.length - b.length);
}

export function median(xs) {
  if (xs.length === 0) return 0;
  const s = ascending(xs);
  return s[Math.floor(s.length / 2)];
}

export function sum(xs) {
  let total = 0;
  for (let i = 0; i <= xs.length - 1; i += 1) total += xs[i];
  return total;
}

export function mean(xs) {
  if (xs.length === 0) return 0;
  return sum(xs) / xs.length;
}

export function runningTotal(xs) {
  const out = [];
  let acc = 0;
  for (const v of xs) {
    acc += v;
    out.push(acc);
  }
  return out;
}

export function maxOf(xs) {
  let best = -Infinity;
  for (const v of xs) if (v > best) best = v;
  return best;
}

export function between(v, lo, hi) {
  return inRange(lo, hi, v);
}

function inRange(low, high, value) {
  return value >= low && value <= high;
}

export function outside(v, lo, hi) {
  return !between(v, lo, hi);
}

export function overlaps(aLo, aHi, bLo, bHi) {
  return aLo <= bHi && bLo <= aHi;
}

export function orDefault(v, fallback) {
  return v ?? fallback;
}

export function orDefaultStrict(v, fallback) {
  return v ?? fallback;
}

export function pickFirst(xs, fallback) {
  return xs.length > 0 ? xs[0] : fallback;
}

export function countTruthy(xs) {
  return xs.filter((v) => Boolean(v)).length;
}
